/* eslint-disable @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return -- this file reshapes an OpenAPI document, which is untyped JSON by nature */
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

/**
 * Lints the committed public contract (docs/openapi/openapi.json). It is
 * regenerated by `yarn openapi:generate` and CI fails when the file is stale,
 * so what is checked here is what SDK maintainers download.
 */
type Json = Record<string, any>;

const root = join(__dirname, '..', '..', '..', '..');
const document = JSON.parse(
  readFileSync(join(root, 'docs', 'openapi', 'openapi.json'), 'utf8'),
) as Json;

const METHODS = ['get', 'post', 'put', 'patch', 'delete'];
const operations: { method: string; path: string; op: Json }[] = Object.entries(
  document.paths as Json,
).flatMap(([path, item]) =>
  METHODS.filter((method) => item[method]).map((method) => ({
    method,
    path,
    op: item[method] as Json,
  })),
);

/** Routes that must never be published: sessions, admin, protocols, inbound webhooks, internals. */
const EXCLUDED = [
  /^\/auth/,
  /^\/session/,
  /^\/platform/,
  /^\/admin/,
  /^\/mcp/,
  /\.well-known/,
  /^\/api-keys/,
  /^\/otp/,
  /^\/turnstile/,
  /^\/public-config/,
  /^\/webhooks\/(stripe|woovi)/,
  /^\/integrations\/inbound/,
  /^\/health\/ready/,
  /^\/billing\/(checkout|subscribe|portal|payments|plan-change|pix)/,
  /^\/customers\/registry/,
  /^\/invoice-package-links/,
  /^\/plans\/recommend/,
];

function resolve(ref: string): unknown {
  return ref
    .replace(/^#\//, '')
    .split('/')
    .reduce<any>((node, key) => node?.[key], document);
}

function refs(node: unknown, found: string[] = []): string[] {
  if (Array.isArray(node)) node.forEach((item) => refs(item, found));
  else if (node && typeof node === 'object')
    for (const [key, value] of Object.entries(node))
      if (key === '$ref' && typeof value === 'string') found.push(value);
      else refs(value, found);
  return found;
}

describe('public OpenAPI contract', () => {
  it('describes the API and where it lives', () => {
    expect(document.openapi).toMatch(/^3\.0\./);
    expect(document.info.title).toBe('Corvo API');
    expect(document.servers[0].url).toBe('https://api.corvo.tech/v1');
    expect(document.components.securitySchemes.ApiKeyAuth).toMatchObject({
      type: 'apiKey',
      in: 'header',
      name: 'x-api-key',
    });
  });

  it('contains the operations the SDKs call', () => {
    const ids = new Set(operations.map(({ op }) => op.operationId));
    for (const id of [
      'invoices_create',
      'invoices_createBatch',
      'invoices_list',
      'invoices_get',
      'invoices_cancel',
      'invoices_substitute',
      'invoices_sendEmail',
      'invoices_overview',
      'invoicePackage_download',
      'cnpj_lookup',
      'customers_search',
      'customers_update',
      'customers_delete',
      'serviceFavorites_list',
      'accountantPackage_send',
      'dpsSequence_set',
      'fiscalProfiles_upsert',
      'serviceTaxProfiles_create',
      'schedules_list',
      'imports_start',
      'companies_create',
      'certificates_upload',
      'webhooks_create',
      'credits_getBalance',
      'billing_getPlan',
      'health_live',
    ])
      expect(ids).toContain(id);
  });

  it('has a unique, well formed operationId on every operation', () => {
    const ids = operations.map(({ op }) => op.operationId as string);
    expect(new Set(ids).size).toBe(ids.length);
    for (const id of ids) expect(id).toMatch(/^[a-z][A-Za-z]*_[a-z][A-Za-z]*$/);
  });

  it('publishes no session, admin, protocol or provider-inbound route', () => {
    for (const { path } of operations)
      for (const excluded of EXCLUDED) expect(path).not.toMatch(excluded);
  });

  it('documents every operation', () => {
    for (const { method, path, op } of operations) {
      const name = `${method.toUpperCase()} ${path}`;
      expect({ name, summary: Boolean(op.summary) }).toEqual({
        name,
        summary: true,
      });
      expect({ name, description: Boolean(op.description) }).toEqual({
        name,
        description: true,
      });
      expect(op.tags).toHaveLength(1);
      expect(Array.isArray(op.security)).toBe(true);
    }
  });

  it('gives every success response a real schema (no empty object, no any)', () => {
    for (const { method, path, op } of operations) {
      const name = `${method.toUpperCase()} ${path}`;
      const successes = Object.entries(op.responses as Json).filter(
        ([status]) => status.startsWith('2'),
      );
      expect({ name, count: successes.length > 0 }).toEqual({
        name,
        count: true,
      });
      for (const [status, response] of successes) {
        if (status === '204') continue;
        const content: Json[] = Object.values((response as Json).content ?? {});
        expect({ name, status, hasContent: content.length > 0 }).toEqual({
          name,
          status,
          hasContent: true,
        });
        for (const media of content) {
          const schema = media.schema as Json;
          expect(Object.keys(schema).length).toBeGreaterThan(0);
          const data = schema.properties?.data as Json | undefined;
          if (data !== undefined)
            expect({ name, empty: Object.keys(data).length === 0 }).toEqual({
              name,
              empty: false,
            });
          if (schema.properties?.pagination !== undefined)
            expect(schema.properties.data.type).toBe('array');
        }
      }
    }
  });

  it('answers errors with the ApiError schema and rate-limit headers', () => {
    expect(document.components.schemas.ApiError.required).toEqual(
      expect.arrayContaining(['statusCode', 'code', 'message']),
    );
    const tooMany = document.components.responses.Error429;
    expect(tooMany.headers['Retry-After']).toBeDefined();
    for (const { op } of operations) {
      expect(op.responses['500']).toBeDefined();
      for (const [status, response] of Object.entries(op.responses as Json)) {
        if (!status.startsWith('2')) continue;
        if (status === '204') continue;
        expect(Object.keys((response as Json).headers ?? {})).toEqual(
          expect.arrayContaining([
            'X-RateLimit-Limit',
            'X-RateLimit-Remaining',
          ]),
        );
      }
    }
  });

  it('marks the Idempotency-Key on the idempotent POSTs', () => {
    for (const key of [
      ['/invoices', 'post'],
      ['/invoices/{id}/email', 'post'],
      ['/invoices/{id}/substitute', 'post'],
    ]) {
      const params = (document.paths[key[0]][key[1]].parameters ??
        []) as Json[];
      expect(params.map((param) => param.$ref)).toContain(
        '#/components/parameters/IdempotencyKey',
      );
    }
  });

  it('serves files with their media type', () => {
    const type = (path: string) =>
      Object.keys(document.paths[path].get.responses['200'].content)[0];
    expect(type('/invoices/{id}/pdf')).toBe('application/pdf');
    expect(type('/invoices/{id}/xml')).toBe('application/xml');
    expect(type('/companies/{companyId}/invoice-package')).toBe(
      'application/zip',
    );
    expect(type('/imports/template')).toBe('text/csv');
    expect(
      document.paths['/companies/{companyId}/certificates'].post.requestBody
        .content['multipart/form-data'].schema.properties.file.format,
    ).toBe('binary');
  });

  it('keeps enums current', () => {
    const invoice = document.components.schemas.Invoice.properties;
    expect([...invoice.status.enum].sort()).toEqual(
      [
        'queued',
        'processing',
        'authorized',
        'rejected',
        'retry_pending',
        'reconciliation_required',
        'manual_review',
        'failed',
        'cancelling',
        'cancelled',
      ].sort(),
    );
    expect(document.components.schemas.Plan.properties.slug.enum).toEqual(
      expect.arrayContaining(['free', 'solo', 'equipe', 'empresa', 'escala']),
    );
    expect(document.components.schemas.Plan.properties.slug.enum).not.toEqual(
      expect.arrayContaining(['growth']),
    );
    expect(document.components.schemas.WebhookEventType.enum).toEqual(
      expect.arrayContaining([
        'nfse.invoice.authorized',
        'nfse.invoice.manual_review',
        'nfse.invoice.taker_rejected',
      ]),
    );
    expect(
      document.components.schemas.ApiError.properties.code['x-known-values'],
    ).toContain('ERROR_IDEMPOTENCY_CONFLICT');
    expect(invoice.lastErrorCode.description).toContain(
      'DPS_NUMBER_ALREADY_USED',
    );
  });

  it('has no dangling or unused references', () => {
    const used = new Set<string>();
    for (const ref of refs(document)) {
      expect({ ref, found: resolve(ref) !== undefined }).toEqual({
        ref,
        found: true,
      });
      const match = /^#\/components\/schemas\/(.+)$/.exec(ref);
      if (match) used.add(match[1]);
    }
    for (const name of Object.keys(document.components.schemas))
      expect({ name, used: used.has(name) }).toEqual({ name, used: true });
  });
});
